Evan — thanks for the quick turnaround and the requirements doc. Below is a compact checklist to share with your SRE and backend teams plus two minimal code samples you can drop into your service templates. Let us know if you want a short pairing session for the installer.

Minimum Integration Checklist (to mark complete in sandbox):
- [ ] Installer (redwood-bridge v0.9+) added to service dependency and loaded as early as auth initialization.
- [ ] Egress token retrieval wired: client fetches from Vault, caches token for up to 6h, rotates on expiration.
- [ ] Client timeouts & retry wrapper implemented (see snippet).
- [ ] Telemetry hook enabled (ENV REDWOOD_TELEMETRY=true) and prefix-level metrics observed in Console.
- [ ] Rate-limiting client: implement token-bucket smoothing with capacity = 20, refill = 10 req/s.
- [ ] Staged cutover routes created and health checks pass for 48h at 1% and 10% traffic.

Example: Node.js retry wrapper (minimal)
-----js
const fetch = require('node-fetch');
async function redwoodCall(url, opts = {}) {
  const maxAttempts = 3;
  let attempt = 0;
  let delay = 200;
  while (true) {
    attempt++;
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 8000); // 8s total deadline
      const res = await fetch(url, { ...opts, signal: controller.signal });
      clearTimeout(timeout);
      if (res.status === 429 || res.status >= 500) {
        if (attempt >= maxAttempts) throw new Error(`failed after ${attempt}`);
        const jitter = 0.5 + Math.random() * 0.5;
        await new Promise(r => setTimeout(r, Math.round(delay * jitter)));
        delay = Math.min(5000, delay * 2);
        continue;
      }
      return res;
    } catch (err) {
      if (attempt >= maxAttempts) throw err;
      const jitter = 0.5 + Math.random() * 0.5;
      await new Promise(r => setTimeout(r, Math.round(delay * jitter)));
      delay = Math.min(5000, delay * 2);
    }
  }
}
-----

Example: Go snippet (net/http)
-----go
func RedwoodCall(client *http.Client, req *http.Request) (*http.Response, error) {
  maxAttempts := 3
  delay := 200 * time.Millisecond
  for attempt := 1; attempt <= maxAttempts; attempt++ {
    ctx, cancel := context.WithTimeout(req.Context(), 8*time.Second)
    defer cancel()
    req = req.WithContext(ctx)
    res, err := client.Do(req)
    if err == nil && res.StatusCode < 500 && res.StatusCode != 429 {
      return res, nil
    }
    if attempt == maxAttempts {
      return res, fmt.Errorf("request failed after %d attempts: %v", attempt, err)
    }
    jitter := 0.5 + rand.Float64()*0.5
    time.Sleep(time.Duration(float64(delay) * jitter))
    delay = time.Duration(math.Min(float64(5*time.Second), float64(delay)*2))
  }
  return nil, fmt.Errorf("unreachable")
}
-----

Operational notes:
- Env vars: REDWOOD_API_ENDPOINT, REDWOOD_EGRESS_TOKEN, REDWOOD_TELEMETRY.
- If you expect high burst traffic at predictable times, open a short RFC with us and we can temporarily raise quota for the window.
- We'll provide a DocuSign for the SLA addendum if Sparrow wants higher baseline throughput.

